<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
$user=require_login(['office_head','office_staff']);$officeId=(int)$user['office_id'];$dateFrom=trim((string)($_GET['date_from']??''));$dateTo=trim((string)($_GET['date_to']??''));$where=['f.office_id=?'];$params=[$officeId];if($dateFrom!==''){$where[]='f.visit_date>=?';$params[]=$dateFrom;}if($dateTo!==''){$where[]='f.visit_date<=?';$params[]=$dateTo;}$stmt=db()->prepare("SELECT f.* FROM feedback f WHERE ".implode(' AND ',$where)." ORDER BY f.visit_date DESC");$stmt->execute($params);$rows=$stmt->fetchAll();
if(($_GET['export']??'')==='csv'){$export=[];foreach($rows as $r)$export[]=[$r['id'],$r['visit_date'],$r['sex'],$r['age'],$r['client_type'],$r['service_received'],$r['timeliness_rating'],$r['client_handling_rating'],$r['quality_rating'],$r['overall_rating'],$r['average_rating'],$r['comment'],$r['sentiment'],$r['sentiment_confidence'],$r['sentiment_source'],$r['final_score'],$r['source'],$r['submitted_at']];csv_download(strtolower($user['office_code']).'-feedback-'.date('Y-m-d').'.csv',['ID','Visit Date','Sex','Age','Client Type','Service','Timeliness','Client Handling','Quality','Overall','Average Rating','Comment','Sentiment','Confidence','Classifier Source','Final Score','Record Source','Submitted At'],$export);}
$m=dashboard_metrics($officeId);render_dashboard_start('Office Reports','reports');page_header($user['office_code'].' Reports & Export','Print or export only records from '.$user['office_name'].'.','<button class="btn secondary" onclick="window.print()">Print / Save as PDF</button>');
?>
<form class="filters" method="get"><input type="date" name="date_from" value="<?= e($dateFrom) ?>"><input type="date" name="date_to" value="<?= e($dateTo) ?>"><button class="btn">Generate</button><button class="btn success" name="export" value="csv">Download CSV</button></form>
<div class="stats-grid"><div class="stat-card"><small>Responses</small><strong><?= $m['total'] ?></strong></div><div class="stat-card"><small>Average Rating</small><strong><?= number_format($m['avg_rating'],2) ?>/4</strong></div><div class="stat-card"><small>Final Score</small><strong><?= number_format($m['avg_final'],2) ?>%</strong></div><div class="stat-card"><small>Positive Rate</small><strong><?= number_format($m['positive_rate'],1) ?>%</strong></div><div class="stat-card"><small>Action Completion</small><strong><?= number_format($m['completion_rate'],1) ?>%</strong></div></div>
<section class="card"><div class="card-head"><div><h2><?= e($user['office_name']) ?> Feedback Report</h2><p><?= count($rows) ?> record(s) in the selected date range</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Service</th><th>Client Type</th><th>Rating</th><th>Sentiment</th><th>Final</th><th>Comment</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e($r['visit_date']) ?></td><td><?= e($r['service_received']) ?></td><td><?= e($r['client_type']) ?></td><td><?= number_format((float)$r['average_rating'],2) ?>/4</td><td><?= e(status_label($r['sentiment'])) ?></td><td><?= number_format((float)$r['final_score'],2) ?>%</td><td><?= e($r['comment']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php render_dashboard_end(); ?>
